const button=document.querySelector('#theme');function setTheme(light){document.body.classList.toggle('light',light);button.textContent=light?'☀':'☾';button.setAttribute('aria-label',light?'Switch to dark theme':'Switch to light theme')}try{setTheme(localStorage.getItem('oumaima-theme')==='light')}catch{}button.addEventListener('click',()=>{const light=!document.body.classList.contains('light');setTheme(light);try{localStorage.setItem('oumaima-theme',light?'light':'dark')}catch{}});function tick(){document.querySelector('#clock').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Casablanca',hour:'2-digit',minute:'2-digit'}).format(new Date())}tick();setInterval(tick,30000);